			text = [=[Rexxar is a wanderer and a beastmaster, a warrior of mingled {link:orcs}orc{/link} and {link:ogres}ogre{/link} blood who walks the wild places of {link:kalimdor}Kalimdor{/link} with a great bear named Misha at his side. He belongs to no clan and keeps no home. Yet when the {link:horde}Horde{/link} was in its greatest need after the founding of {link:durotar}Durotar{/link}, it was Rexxar who answered, and {link:thrall}Thrall{/link} still names him among his champions. In these days he walks the long road of {link:desolace}Desolace{/link}, from the edge of {link:stonetalon-mountains}Stonetalon{/link} to the forests of {link:feralas}Feralas{/link}, and those who wish to find him must walk it too.]=],
		},
		{
			title = "Significance",
			text = [=[Rexxar is one of the heroes of the young {link:horde}Horde{/link}. He carries no banner and asks for no reward. He fought for {link:thrall}Thrall{/link} because the cause was just, and then he went back to the wilds. That he remains a friend of the Warchief, and still serves him when called, is proof of how deeply the Horde trusts him.]=],
		},
		{
			title = "Deeds",
			text = [=[• He wandered alone for many years before he came to the aid of the {link:horde}Horde{/link}.
• He fought beside {link:thrall}Thrall{/link}'s people when Grand Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link} brought his fleet to destroy {link:durotar}Durotar{/link}, and he was among those who carried the war to the admiral.
• He rescued {link:baine-bloodhoof}Baine{/link}, the son of {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, when the {link:centaurs}centaur{/link} took him captive in {link:mulgore}Mulgore{/link}.
• He walks the wastes of {link:desolace}Desolace{/link}, and the Warchief knows where to find him.
• He has found a way into the lair of the black dragon of the south, and he offers it to those whom the Warchief sends.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The chronicles say little of Rexxar's life before the war against the admiral, or of what drove him into solitude. This entry records only what the histories and his deeds in {link:desolace}Desolace{/link} reveal.]=],
		},
	},
	chapters = {
		{
			key = "the-beastmaster-s-war",
			title = "The Beastmaster's War",
			hint = [=[Learn the tale of the wanderer who answered the Warchief's call.]=],
			unlock = {
				{ type = "interact" },
			},
			text = [=[After the orcs founded their new home, the fleet of {link:kul-tiras}Kul Tiras{/link} came to finish them. Rexxar was drawn into the war almost against his will. He gathered allies where he found them, among the trolls, the {link:tauren}tauren{/link} and stranger folk, and he fought beside them from the coast of {link:durotar}Durotar{/link} to the marshes of {link:theramore-isle}Theramore{/link}. When the admiral had fallen, Rexxar did not stay to claim honors. He walked back into the wild, with Misha at his side.]=],
		},
		{
			key = "the-way-into-the-lair",
			title = "The Way into the Lair",
			hint = [=[Answer the Warchief's summons and seek out his champion in Desolace.]=],
			unlock = {
				{ type = "quest", id = 6567 },
			},
			text = [=[Word went out from {link:orgrimmar}Orgrimmar{/link} that one of the Warchief's champions had found a way into the lair of a great black dragon. Rexxar had studied the black dragonflight long enough to know that only the strongest of its servants may enter, and only with a key enchanted by its general. There was no such key for an outsider, so Rexxar proposed a deception. He sent a letter to an old friend in {link:lordaeron}Lordaeron{/link}, an exile skilled in illusions, and the letter held not a single written word.]=],
		},
		{
			key = "the-blood-of-the-general",
			title = "The Blood of the General",
			hint = "Carry out the beastmaster's plan to its end.",
			unlock = {
				{ type = "quest", id = 6602 },
			},
			text = [=[The illusion opened a door, but the key needed the blood of the dragonflight's general to wake. Rexxar did not pretend the task was a small one. When it was done, he gave the finished amulet into the hands of those who had earned it, and he told them to bring victory to the {link:horde}Horde{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[The Champion of the {link:horde}Horde{/link}, the Warchief's summons]=],
			unlock = {
				{ type = "quest", id = 6567 },
			},
		},
		{
			text = "The Testament of Rexxar",
			unlock = {
				{ type = "quest", id = 6568 },
			},
		},
		{
			text = "Ascension...",
			unlock = {
				{ type = "quest", id = 6601 },
			},
		},
		{
			text = "Blood of the Black Dragon Champion",
			unlock = {
				{ type = "quest", id = 6602 },
			},
		},
	},
	bonds = {
